cd /tmp && cat > extract.js <<'EOF'
const fs=require('fs'),vm=require('vm');
const html=fs.readFileSync('opencode_share.html','utf8');
const scripts=[...html.matchAll(/<script(?:\s[^>]*)?>([\s\S]*?)<\/script>/g)].map(m=>m[1]).filter(s=>s.trim());
const ctx={console,Promise,JSON,Object,Array,Set,Map,Date,String,Number,Boolean,Math,RegExp,Error};
ctx.self=ctx; ctx.globalThis=ctx;
vm.createContext(ctx);
for(const s of scripts){
  try{ vm.runInContext(s,ctx,{timeout:60000}); }
  catch(e){ console.error('ERR:',e.message.slice(0,200)); }
}
const R=ctx.$R;
console.log('R length', R.length);
const root=R[7];
console.log('root keys', Object.keys(root));
fs.writeFileSync('share_raw.json', JSON.stringify(root));
console.log('wrote share_raw.json', fs.statSync('share_raw.json').size);
EOF
node extract.js

