cd /tmp && python3 - <<'EOF'
import json
a=json.load(open('cgpt_flat.json'))
def hydrate(i,depth=0):
    v=a[i]
    if isinstance(v,list): return [hydrate(x,depth+1) for x in v]
    if isinstance(v,dict):
        out={}
        for k,idx in v.items():
            key = k[1:] if k.startswith('_') else k
            out[key]=hydrate(idx,depth+1)
        return out
    if isinstance(v,str):
        # strings are literal strings unless they are pure digits? devalue uses negative for special
        return v
    if isinstance(v,int):
        return {v}  # special markers: -1 undefined, -2 hole, -3 nan, -4 inf, -5 -inf, -6 -0
    return v
EOF
